create table if not exists users(id uuid primary key default gen_random_uuid(),email text unique not null,created_at timestamptz default now());
create table if not exists twitter_tokens(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,twitter_user_id text not null,access_token text not null,refresh_token text not null,expires_at timestamptz not null,scope text,is_premium boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists scheduled_posts(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,content jsonb not null,scheduled_at timestamptz not null,status text default 'PENDING',x_tweet_id text,error_message text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists auto_dm_campaigns(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,parent_tweet_id text not null,trigger_keyword text not null,dm_message text not null,is_active boolean default true,last_polled_at timestamptz,scheduled_post_id uuid unique references scheduled_posts(id) on delete set null,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists dm_logs(id uuid primary key default gen_random_uuid(),campaign_id uuid references auto_dm_campaigns(id) on delete cascade,recipient_twitter_id text not null,sent_at timestamptz default now(),reply_text text,reply_tweet_id text,unique(campaign_id,recipient_twitter_id));